INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('3737', '1582', 'bot', '<p class=\'mb-2\'>Here is the annual tuition fee breakdown for SOET degree programs:</p><p class=\'mb-2\'>• <strong>B.Tech in Computer Science & Engineering (BTECH-CSE)</strong>: ₹150,000 / year<br />\n• <strong>B.Tech in Electronics & Communication Engineering (BTECH-ECE)</strong>: ₹140,000 / year<br />\n• <strong>B.Tech in CSE (Cyber Security & Digital Forensics) (BTECH-CS)</strong>: ₹150,000 / year<br />\n• <strong>M.Tech in Computer Science & Engineering (MTECH-CSE)</strong>: ₹100,000 / year<br />\n• <strong>B.Tech in CSE (Artificial Intelligence & Machine Learning) (BTECH-AIML)</strong>: ₹150,000 / year<br />\n• <strong>B.Tech in Mechanical & Automation Engineering (BTECH-MECH)</strong>: ₹130,000 / year<br />\n• <strong>B.Tech in Civil Engineering (BTECH-CIVIL)</strong>: ₹130,000 / year<br />\n• <strong>Integrated 6-Year B.Tech Program (After 10th Class) (INT-BTECH)</strong>: ₹110,000 / year</p><p class=\'mb-2\'>Government SC/ST/OBC scholarships and MGM Merit Scholarships are available.</p><div class=\'mt-2 pt-1 border-top border-light text-end\'><a href=\'http://localhost:8000/chatbot/courses.php\' class=\'text-primary small text-decoration-none fw-semibold\' target=\'_blank\'>View Details <i class=\'fa-solid fa-arrow-up-right-from-square ms-1\' style=\'font-size:10px;\'></i></a></div>', 'TRAINING_KNOWLEDGE', 'PROGRAM', '0.96', '2026-09-07 14:43:51');
