INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('3747', '1584', 'bot', '<p class=\'mb-2\'>We offer the following official degree programs and academic branches:</p><ol class=\'ps-3 mb-2 small\'><li class=\'mb-1\'><strong>B.Tech in Civil Engineering (BTECH-CIVIL)</strong> — Duration: 4 Years (8 Semesters), Intake: 60 seats</li><li class=\'mb-1\'><strong>B.Tech in Computer Science & Engineering (BTECH-CSE)</strong> — Duration: 4 Years (8 Semesters), Intake: 120 seats</li><li class=\'mb-1\'><strong>B.Tech in CSE (Artificial Intelligence & Machine Learning) (BTECH-AIML)</strong> — Duration: 4 Years (8 Semesters), Intake: 60 seats</li><li class=\'mb-1\'><strong>B.Tech in CSE (Cyber Security & Digital Forensics) (BTECH-CS)</strong> — Duration: 4 Years (8 Semesters), Intake: 60 seats</li><li class=\'mb-1\'><strong>B.Tech in Electronics & Communication Engineering (BTECH-ECE)</strong> — Duration: 4 Years (8 Semesters), Intake: 60 seats</li><li class=\'mb-1\'><strong>B.Tech in Mechanical & Automation Engineering (BTECH-MECH)</strong> — Duration: 4 Years (8 Semesters), Intake: 60 seats</li><li class=\'mb-1\'><strong>Integrated 6-Year B.Tech Program (After 10th Class) (INT-BTECH)</strong> — Duration: 6 Years (12 Semesters), Intake: 60 seats</li><li class=\'mb-1\'><strong>M.Tech in Computer Science & Engineering (MTECH-CSE)</strong> — Duration: 2 Years (4 Semesters), Intake: 30 seats</li></ol><div class=\'mt-2 pt-1 border-top border-light text-end\'><a href=\'http://localhost:8000/courses.php\' class=\'text-primary small text-decoration-none fw-semibold\' target=\'_blank\'>View Details <i class=\'fa-solid fa-arrow-up-right-from-square ms-1\' style=\'font-size:10px;\'></i></a></div>', 'DATABASE', 'PROGRAM', '0.96', '2026-09-16 15:22:09');
