INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('3764', '1582', 'user', 'Write a C program for binary search and explain it', 'system', 'USER_INPUT', '1.00', '2026-09-16 15:24:29');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('3765', '1582', 'bot', '<p class=\'mb-2\'>SOET offers B.Tech in Civil Engineering (BTECH-CIVIL) under Civil Engineering. Duration: 4 Years (8 Semesters). Intake Capacity: 60 seats. Description: Structural engineering, smart infrastructure, BIM planning, geotechnical analysis, transportation networks, and environmental engineering..</p><p class=\'mb-2\'>Binary search is an efficient O(log n) algorithm that finds a target value in a sorted array by repeatedly dividing the search interval in half.</p><p class=\'mb-2\'><div class=\'code-block-wrapper my-2\'><div class=\'code-block-header d-flex justify-content-between px-3 py-1 bg-dark text-white-50 rounded-top small font-monospace\'><span>c</span><button class=\'btn btn-link btn-sm text-white-50 p-0 copy-code-btn\' onclick=\'navigator.clipboard.writeText(this.parentNode.nextElementSibling.innerText)\'><i class=\'fa-regular fa-copy me-1\'></i>Copy</button></div><pre class=\'bg-dark text-light p-3 rounded-bottom mb-0 font-monospace\' style=\'max-height:300px; overflow-y:auto;\'><code>int search(int a[], int n, int x) {<br />\n    int l = 0, r = n - 1;<br />\n    while (l &lt;= r) {<br />\n        int m = l + (r - l) / 2;<br />\n        if (a[m] == x) return m;<br />\n        if (a[m] &lt; x) l = m + 1; else r = m - 1;<br />\n    }<br />\n    return -1;<br />\n}</code></pre></div></p><div class=\'mt-2 pt-1 border-top border-light text-end\'><a href=\'http://localhost:8000/chatbot/courses.php\' class=\'text-primary small text-decoration-none fw-semibold\' target=\'_blank\'>View Details <i class=\'fa-solid fa-arrow-up-right-from-square ms-1\' style=\'font-size:10px;\'></i></a></div>', 'MIXED', 'CODING', '0.95', '2026-09-16 15:24:29');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('3766', '1582', 'user', 'Tell me about the campus research labs and facilities', 'system', 'USER_INPUT', '1.00', '2026-09-16 15:24:30');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('3767', '1582', 'bot', '<p class=\'mb-2\'>SOET campus provides modern hostel accommodation, computer labs, digital library, sports complex, canteen, and bus transport facilities.</p><div class=\'mt-2 pt-1 border-top border-light text-end\'><a href=\'http://localhost:8000/chatbot/contact.php\' class=\'text-primary small text-decoration-none fw-semibold\' target=\'_blank\'>View Details <i class=\'fa-solid fa-arrow-up-right-from-square ms-1\' style=\'font-size:10px;\'></i></a></div>', 'TRAINING_KNOWLEDGE', 'GENERAL_AI', '0.96', '2026-09-16 15:24:30');
