INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('3771', '1582', 'bot', '<p class=\'mb-2\'>SOET MGM University is led by <strong>Dr. Parminder Kaur Dhingra</strong>, Dean & Director, SOET MGM University.</p><p class=\'mb-2\'><strong>Dean & Director\'s Leadership Message:</strong><br />\n\"At SOET MGM University, we are committed to providing top-tier technological education with modern laboratories, expert faculty, and high-paying industry placements. Our mission is to produce innovative, ethically driven engineering professionals.\"</p><div class=\'mt-2 pt-1 border-top border-light text-end\'><a href=\'http://localhost:8000/chatbot/about.php\' class=\'text-primary small text-decoration-none fw-semibold\' target=\'_blank\'>View Details <i class=\'fa-solid fa-arrow-up-right-from-square ms-1\' style=\'font-size:10px;\'></i></a></div>', 'DATABASE', 'FACULTY', '0.96', '2026-09-16 15:24:34');
