INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('3781', '1582', 'bot', '<p class=\'mb-2\'>Admissions to B.Tech programs at SOET MGM University are open for candidates passing 10+2 with 45% aggregate in Physics, Mathematics, and Chemistry/Computer Science (40% for SC/ST/OBC). Valid MHT-CET or JEE Main scores are accepted, and direct institute-level quota admissions are available. You can apply and track applications online at /admissions.php.</p><div class=\'mt-2 pt-1 border-top border-light text-end\'><a href=\'http://localhost:8000/chatbot/admissions.php\' class=\'text-primary small text-decoration-none fw-semibold\' target=\'_blank\'>View Details <i class=\'fa-solid fa-arrow-up-right-from-square ms-1\' style=\'font-size:10px;\'></i></a></div>', 'DATABASE', 'ADMISSION', '0.96', '2026-09-16 15:25:46');
