INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('3789', '1582', 'bot', '<p class=\'mb-2\'><strong>Direct Second Year</strong> refers to a standard subject of knowledge and inquiry. It is primarily understood and applied according to its functional definition and practical context.</p>', 'GENERAL_AI', 'GENERAL_AI', '0.90', '2026-09-16 15:26:13');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('3790', '1582', 'user', 'Is hostellers laundry service free on campus?', 'system', 'USER_INPUT', '1.00', '2026-09-16 15:26:26');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('3791', '1582', 'bot', '<p class=\'mb-2\'>SOET hostel residents have access to automated commercial laundry facilities and washing areas on campus. Basic laundry access is included in the hostel amenity fee, while specialized dry-cleaning services are available at nominal charges.</p><div class=\'mt-2 pt-1 border-top border-light text-end\'><a href=\'http://localhost:8000/chatbot/contact.php\' class=\'text-primary small text-decoration-none fw-semibold\' target=\'_blank\'>View Details <i class=\'fa-solid fa-arrow-up-right-from-square ms-1\' style=\'font-size:10px;\'></i></a></div>', 'TRAINING_KNOWLEDGE', 'GENERAL_AI', '0.96', '2026-09-16 15:26:26');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('3792', '1582', 'user', 'Is hostel facility available on campus?', 'system', 'USER_INPUT', '1.00', '2026-09-16 15:26:36');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('3793', '1582', 'bot', '<p class=\'mb-2\'>Yes, SOET provides separate modern residential hostels for boys and girls with 24/7 security, Wi-Fi, gym, hygienic mess, and medical care.</p><div class=\'mt-2 pt-1 border-top border-light text-end\'><a href=\'http://localhost:8000/chatbot/contact.php\' class=\'text-primary small text-decoration-none fw-semibold\' target=\'_blank\'>View Details <i class=\'fa-solid fa-arrow-up-right-from-square ms-1\' style=\'font-size:10px;\'></i></a></div>', 'TRAINING_KNOWLEDGE', 'GENERAL_AI', '0.96', '2026-09-16 15:26:36');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('3794', '1582', 'user', 'computer lab and wifi campus facilities?', 'system', 'USER_INPUT', '1.00', '2026-09-16 15:26:44');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('3795', '1582', 'bot', '<p class=\'mb-2\'>SOET campus provides modern hostel accommodation, computer labs, digital library, sports complex, canteen, and bus transport facilities.</p><div class=\'mt-2 pt-1 border-top border-light text-end\'><a href=\'http://localhost:8000/chatbot/contact.php\' class=\'text-primary small text-decoration-none fw-semibold\' target=\'_blank\'>View Details <i class=\'fa-solid fa-arrow-up-right-from-square ms-1\' style=\'font-size:10px;\'></i></a></div>', 'TRAINING_KNOWLEDGE', 'GENERAL_AI', '0.96', '2026-09-16 15:26:44');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('3796', '1582', 'user', 'What campus facilities and infrastructure support technical education?', 'system', 'USER_INPUT', '1.00', '2026-09-16 15:26:51');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('3797', '1582', 'bot', '<p class=\'mb-2\'>The campus features modern ICT-enabled smart classrooms, gigabit Wi-Fi connectivity, an Olympic-grade Sports Complex, boys and girls hostels, hygienic canteens, and an Innovation & Incubation Center.</p><div class=\'mt-2 pt-1 border-top border-light text-end\'><a href=\'http://localhost:8000/chatbot/contact.php\' class=\'text-primary small text-decoration-none fw-semibold\' target=\'_blank\'>View Details <i class=\'fa-solid fa-arrow-up-right-from-square ms-1\' style=\'font-size:10px;\'></i></a></div>', 'TRAINING_KNOWLEDGE', 'GENERAL_AI', '0.96', '2026-09-16 15:26:51');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('3798', '1591', 'user', 'Hello', 'system', 'USER_INPUT', '1.00', '2026-09-16 15:27:01');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('3799', '1591', 'bot', '<p class=\'mb-2\'>Hello! I am CampusAI, your intelligent assistant for SOET MGM University. How can I help you today?</p>', 'system', 'GREETING', '1.00', '2026-09-16 15:27:01');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('3800', '1592', 'user', 'What are the B.Tech courses in SOET?', 'system', 'USER_INPUT', '1.00', '2026-09-16 15:27:01');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('3801', '1592', 'bot', '<p class=\'mb-2\'>We offer the following official degree programs and academic branches:</p><ol class=\'ps-3 mb-2 small\'><li class=\'mb-1\'><strong>B.Tech in Civil Engineering (BTECH-CIVIL)</strong> — Duration: 4 Years (8 Semesters), Intake: 60 seats</li><li class=\'mb-1\'><strong>B.Tech in Computer Science & Engineering (BTECH-CSE)</strong> — Duration: 4 Years (8 Semesters), Intake: 120 seats</li><li class=\'mb-1\'><strong>B.Tech in CSE (Artificial Intelligence & Machine Learning) (BTECH-AIML)</strong> — Duration: 4 Years (8 Semesters), Intake: 60 seats</li><li class=\'mb-1\'><strong>B.Tech in CSE (Cyber Security & Digital Forensics) (BTECH-CS)</strong> — Duration: 4 Years (8 Semesters), Intake: 60 seats</li><li class=\'mb-1\'><strong>B.Tech in Electronics & Communication Engineering (BTECH-ECE)</strong> — Duration: 4 Years (8 Semesters), Intake: 60 seats</li><li class=\'mb-1\'><strong>B.Tech in Mechanical & Automation Engineering (BTECH-MECH)</strong> — Duration: 4 Years (8 Semesters), Intake: 60 seats</li><li class=\'mb-1\'><strong>Integrated 6-Year B.Tech Program (After 10th Class) (INT-BTECH)</strong> — Duration: 6 Years (12 Semesters), Intake: 60 seats</li><li class=\'mb-1\'><strong>M.Tech in Computer Science & Engineering (MTECH-CSE)</strong> — Duration: 2 Years (4 Semesters), Intake: 30 seats</li></ol><div class=\'mt-2 pt-1 border-top border-light text-end\'><a href=\'http://localhost:8000/courses.php\' class=\'text-primary small text-decoration-none fw-semibold\' target=\'_blank\'>View Details <i class=\'fa-solid fa-arrow-up-right-from-square ms-1\' style=\'font-size:10px;\'></i></a></div>', 'DATABASE', 'PROGRAM', '0.96', '2026-09-16 15:27:01');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('3802', '1593', 'user', 'What is Artificial Intelligence?', 'system', 'USER_INPUT', '1.00', '2026-09-16 15:27:01');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('3803', '1593', 'bot', '<p class=\'mb-2\'>Artificial Intelligence (AI) is the branch of computer science dedicated to developing systems capable of performing tasks that typically require human cognition, such as reasoning, learning, and perception.</p>', 'GENERAL_AI', 'GENERAL_AI', '0.94', '2026-09-16 15:27:01');
