INSERT INTO `chatbot_categories` (`id`, `name`, `slug`, `description`, `created_at`) VALUES ('7', 'General & FAQs', 'general', 'General college info, campus location, hostel, and contact info', '2026-08-11 15:22:44');
INSERT INTO `chatbot_kb` (`id`, `trigger_words`, `response_text`, `category`, `created_at`) VALUES ('1', 'hello,hi,hey,greetings', 'Hello! Welcome to SOET. How can I assist you with details about courses, admissions, faculty, or placements today?', 'general', '2026-08-03 11:47:48');
INSERT INTO `chatbot_kb` (`id`, `trigger_words`, `response_text`, `category`, `created_at`) VALUES ('2', 'admission,apply,join,register', 'Admissions for B.Tech CSE, ECE, ME, and CE are currently open. You can apply directly through our Admissions page by filling out the form and uploading your marksheet.', 'admissions', '2026-08-03 11:47:48');
INSERT INTO `chatbot_kb` (`id`, `trigger_words`, `response_text`, `category`, `created_at`) VALUES ('3', 'fees,fee,cost,expense,tuition', 'Our fee structure is transparent. B.Tech in CSE is approximately INR 75,000 per odd semester and INR 70,000 per even semester. Other courses range between INR 60,000 and INR 68,000. Check the Course details on our website for detailed semester-wise breakdowns.', 'fees', '2026-08-03 11:47:48');
INSERT INTO `chatbot_kb` (`id`, `trigger_words`, `response_text`, `category`, `created_at`) VALUES ('4', 'courses,course,branch,department,branches,departments', 'SOET offers B.Tech programs in four core areas: 1) Computer Science & Engineering (BTECH-CSE), 2) Electronics & Communication Engineering (BTECH-ECE), 3) Mechanical Engineering (BTECH-ME), and 4) Civil Engineering (BTECH-CE).', 'courses', '2026-08-03 11:47:48');
INSERT INTO `chatbot_kb` (`id`, `trigger_words`, `response_text`, `category`, `created_at`) VALUES ('5', 'placement,placements,job,recruit,package,salary,company', 'SOET has an excellent placement record. Over 85% of CSE students get placed annually. Recruiters include TCS, Wipro, Infosys, Cognizant, and Amazon. The highest package reached INR 18 LPA, with an average package of INR 5.5 LPA.', 'placements', '2026-08-03 11:47:48');
INSERT INTO `chatbot_kb` (`id`, `trigger_words`, `response_text`, `category`, `created_at`) VALUES ('6', 'contact,phone,number,email,address,map,location', 'You can contact us via email at info@soet.edu or call +91 98765 43210. Our campus is located at Knowledge Park III, Greater Noida, UP.', 'general', '2026-08-03 11:47:48');
INSERT INTO `chatbot_kb` (`id`, `trigger_words`, `response_text`, `category`, `created_at`) VALUES ('7', 'faculty,teacher,teachers,professor,professors', 'Our faculty includes highly experienced educators, with many holding Ph.D. degrees from prestigious institutes. You can explore the complete faculty directory under our Faculty page.', 'faculty', '2026-08-03 11:47:48');
INSERT INTO `chatbot_kb` (`id`, `trigger_words`, `response_text`, `category`, `created_at`) VALUES ('8', 'events,event,fest,workshop,seminar', 'We organize tech fests, cultural nights, and industry workshops regularly. You can view all upcoming schedules and register online on our Events page.', 'events', '2026-08-03 11:47:48');
INSERT INTO `chatbot_logs` (`id`, `session_id`, `user_query`, `bot_response`, `created_at`) VALUES ('1', 'jlqkn0ucn2rqa9cu5ds3g4jh1u', 'admission details', 'Admissions for B.Tech CSE, ECE, ME, and CE are currently open. You can apply directly through our Admissions page by filling out the form and uploading your marksheet.', '2026-08-03 13:36:21');
