INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('85', 'Is hostellers laundry service free on campus?', 'SOET hostel residents have access to automated commercial laundry facilities and washing areas on campus. Basic laundry access is included in the hostel amenity fee, while specialized dry-cleaning services are available at nominal charges.', 'facilities', NULL, 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('86', 'Can non-CET candidates get direct management quota admission?', 'Yes, candidates who have not appeared for MHT-CET or JEE Main can apply for Institute Level / Management Quota seats based on their 12th Standard PCM aggregate marks (minimum 45% for general category, 40% for reserved categories). Direct counseling is conducted at the SOET Admission Office.', 'admissions', NULL, 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('87', 'What is the schedule for inter-college sports tournaments?', 'The MGM University Annual Inter-College Sports Festival (including cricket, football, basketball, and athletics) is organized during the winter academic session (December–January). Exact fixture dates, venue schedules, and circulars are published under the Events and Notices section.', 'events', NULL, 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('88', 'check registration EVT-REG-2026-94628', 'Event registration pass EVT-REG-2026-94628 is valid for the scheduled university event. Attendees can present their digital event pass or confirmation SMS at the event check-in desk at the MGM University auditorium.', 'events', NULL, 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('89', 'tell me about aerospace engineering syllabus at soet', 'This information is not currently available in our website database or official records, as SOET does not currently offer Aerospace Engineering. Available B.Tech degree branches include CSE, AI & ML, Cyber Security, ECE, Mechanical, and Civil Engineering.', 'academics', NULL, 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('90', 'coureses', 'SOET MGM University offers B.Tech programs in Civil, Computer Science, CSE (AI & ML), CSE (Cyber Security), ECE, Mechanical Engineering, Integrated 6-Year B.Tech (after 10th), and M.Tech in Computer Science & Engineering.', 'academics', NULL, 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('91', 'live sae', 'Real-time engineering seat availability and vacancy metrics can be checked directly through CampusAI or on the Admissions portal, showing vacant versus filled seats across all B.Tech branches.', 'admissions', NULL, 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
