INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('93', 'blogs', 'Explore student and faculty technical articles, campus stories, and innovation research on the official SOET Media Blog Portal at /blogs.php. Students can also submit new blog drafts via /submit-blog.php.', 'general', NULL, 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('94', 'feedback', 'We welcome your suggestions and inquiries. You can share your feedback directly using the thumbs-up/down buttons in this chat, or submit an official contact message at /contact.php.', 'general', NULL, 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('95', 'what is quantum computing', 'Quantum computing is a multidisciplinary field utilizing principles of quantum mechanics—such as superposition and entanglement—to perform complex computations exponentially faster than classical computers for specific problem classes.', 'technical', NULL, 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('96', 'tell me about python', 'Python is a high-level, interpreted programming language renowned for its clean syntax and readability. It is widely used across web development, data science, automation, and artificial intelligence.', 'technical', NULL, 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('97', 'what is date today', 'Today is Thursday, September 3, 2026.', 'general', NULL, 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
