INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('99', 'what is 25 * 4', '`25 * 4 = 100`', 'general', NULL, 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('100', 'who are you', 'I am CampusAI, the official intelligent assistant for SOET MGM University, designed to answer college inquiries and general or technical questions directly.', 'general', NULL, 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('101', 'who is prime minister of india', 'The Prime Minister of India is Narendra Modi, who has served as the head of government since May 2014.', 'general', NULL, 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('102', 'usa', 'The United States of America (USA) is a federal republic composed of 50 states, primarily located in North America, with its capital in Washington, D.C.', 'general', NULL, 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('103', 'What is artificial intelligence (AI)?', 'Artificial Intelligence (AI) is the branch of computer science dedicated to developing software systems capable of performing tasks that typically require human cognition, such as reasoning, problem-solving, visual perception, and decision-making.', 'ai_tech', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:41');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('104', 'What is machine learning (ML)?', 'Machine learning is a subset of AI where mathematical algorithms learn statistical patterns from historical data to make predictions or automated decisions without being explicitly programmed.', 'ai_tech', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:41');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('105', 'What is ChatGPT?', 'ChatGPT is an artificial intelligence conversational model developed by OpenAI. Built on Large Language Models (LLMs), it engages in natural dialogue, writes and debugs code, and synthesizes complex information.', 'ai_tech', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:41');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('106', 'What is cybersecurity?', 'Cybersecurity is the practice of protecting computer systems, cloud networks, digital devices, and sensitive organizational data from unauthorized access, cyberattacks, theft, and damage.', 'ai_tech', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:41');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('107', 'What is the Internet of Things (IoT)?', 'The Internet of Things (IoT) refers to an interconnected network of physical devices embedded with sensors, microcontrollers, and wireless connectivity that autonomously collect and exchange operational data in real time.', 'ai_tech', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:41');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('108', 'What is blockchain technology?', 'Blockchain is a decentralized, cryptographically secured distributed digital ledger that chronologically records transactions across a peer-to-peer network, ensuring tamper-proof immutability without requiring a central intermediary.', 'ai_tech', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:41');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('109', 'What is data science?', 'Data science is an interdisciplinary field combining statistics, advanced mathematics, domain expertise, and machine learning programming to discover actionable patterns and predictive insights from structured and unstructured data.', 'ai_tech', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:41');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('110', 'What is quantum computing?', 'Quantum computing harnesses fundamental principles of quantum mechanics—such as superposition and quantum entanglement—to solve specialized mathematical and optimization problems exponentially faster than classical supercomputers.', 'ai_tech', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:41');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('111', 'What is digital transformation?', 'Digital transformation is the strategic integration of modern digital technology across all operational areas of an organization, fundamentally modernizing operational efficiency and customer value delivery.', 'ai_tech', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:41');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('112', 'What is Python?', 'Python is a high-level, interpreted programming language known for its concise syntax and dynamic typing. It is widely used across backend web development, data science, scientific computing, automation, and artificial intelligence.', 'programming', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:41');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('113', 'What is Java and how does it achieve portability?', 'Java is an object-oriented, class-based language built on the \'Write Once, Run Anywhere\' (WORA) philosophy. Compiled Java bytecode executes within a Java Virtual Machine (JVM), ensuring seamless cross-platform execution.', 'programming', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:41');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('114', 'What is C++ and where is it primarily used?', 'C++ is a high-performance compiled language that combines low-level memory control with object-oriented abstractions. It is the industry standard for game engines, operating system components, embedded firmware, and low-latency financial systems.', 'programming', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:41');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('115', 'What is the difference between HTML and CSS?', 'HTML (HyperText Markup Language) constructs the structural content and semantic hierarchy of a webpage, whereas CSS (Cascading Style Sheets) specifies visual presentation, layout styling, typography, colors, and responsive animations.', 'programming', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('116', 'What is JavaScript and Node.js?', 'JavaScript is a dynamic, lightweight scripting language that powers interactive frontend user experiences. With Node.js, JavaScript executes server-side, enabling unified full-stack web application development.', 'programming', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('117', 'What is Object-Oriented Programming (OOP) and its core pillars?', 'Object-Oriented Programming (OOP) is a software design paradigm structured around reusable classes and stateful objects, governed by four core pillars: Encapsulation, Abstraction, Inheritance, and Polymorphism.', 'programming', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('118', 'What is the difference between a class and an object?', 'A class is an abstract architectural blueprint defining member properties and methods, while an object is a concrete, self-contained instance instantiated in memory holding actual state data.', 'programming', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('119', 'What is an Application Programming Interface (API) and REST?', 'An API is a defined set of communication protocols enabling independent software applications to interact. A REST API leverages standard HTTP methods (GET, POST, PUT, DELETE) and stateless JSON data exchange.', 'programming', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('120', 'What is Git and how does GitHub complement it?', 'Git is a distributed command-line version control system that tracks source code revisions locally, while GitHub is a cloud platform that hosts remote Git repositories, facilitating pull requests, code reviews, and team collaboration.', 'programming', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('121', 'What is Docker and containerization?', 'Docker packages applications and their exact runtime dependencies into lightweight, isolated containers, guaranteeing consistent execution across local development, staging servers, and cloud production environments.', 'programming', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('122', 'What is a Database Management System (DBMS)?', 'A DBMS is system software that manages structured data storage, retrieval, and concurrency while enforcing ACID transaction properties (Atomicity, Consistency, Isolation, Durability).', 'databases', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('123', 'What is the difference between a primary key and a foreign key?', 'A primary key uniquely identifies each individual row within its own table (strictly non-null and unique), whereas a foreign key references a primary key in another table to establish referential relationships.', 'databases', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('124', 'What is database normalization and why is it important?', 'Normalization is the systematic design process of structuring database tables (from 1NF to BCNF) to eliminate redundant data duplication and prevent insertion, update, and deletion anomalies.', 'databases', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('125', 'What is CRUD in database applications?', 'CRUD is an industry acronym for Create, Read, Update, and Delete—the four foundational operations implemented across persistent database storage and RESTful software APIs.', 'databases', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('126', 'What is an Operating System (OS)?', 'An operating system is fundamental system software that coordinates computer hardware, allocates CPU processing time, manages RAM memory and storage I/O, and provides an execution platform for user applications.', 'databases', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('127', 'What is binary search algorithm?', 'Binary search is an efficient O(log n) divide-and-conquer algorithm that locates a target value in a sorted collection by repeatedly halving the search interval.', 'databases', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('128', 'What is an IP address?', 'An IP address (IPv4/IPv6) is a unique numerical network identifier assigned to every hardware device connected to an IP-based computer network for routing packets.', 'databases', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('129', 'What degree programs and engineering branches are offered at SOET?', 'SOET offers 8 approved programs: B.Tech in Civil, Computer Science & Engineering (CSE), CSE (AI & ML), CSE (Cyber Security), ECE, Mechanical Engineering, an Integrated 6-Year B.Tech (after 10th), and M.Tech in CSE.', 'academics', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('130', 'What are the details of the B.Tech Computer Science & Engineering (CSE) program?', 'B.Tech CSE is a 4-year (8 semesters) program with an approved intake of 120 seats. The curriculum covers Data Structures, Algorithms, Operating Systems, Database Management, Cloud Computing, and Full-Stack Development.', 'academics', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('131', 'Does SOET offer specialized programs in Artificial Intelligence and Machine Learning?', 'Yes, SOET offers B.Tech in CSE (Artificial Intelligence & Machine Learning) with an approved intake of 60 seats. Coursework includes Neural Networks, Deep Learning, Computer Vision, and Natural Language Processing.', 'academics', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('132', 'What program is available for students interested in Cyber Security?', 'SOET offers B.Tech in CSE (Cyber Security & Digital Forensics) (60 seats intake), emphasizing Network Security, Ethical Hacking, Cryptographic Protocols, Digital Forensics, and Threat Intelligence.', 'academics', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('133', 'What programs are available after 10th Class?', 'SOET offers an Integrated 6-Year B.Tech Program (INT-BTECH) with an intake of 60 seats, allowing SSC (10th) passed students to complete both diploma-level foundations and a full engineering degree.', 'academics', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('134', 'What post-graduate (M.Tech) engineering programs are available?', 'The college offers M.Tech in Computer Science & Engineering (MTECH-CSE), a 2-year (4 semesters) advanced research degree with an annual intake capacity of 30 seats.', 'academics', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('135', 'What programming languages are taught in the engineering curricula?', 'Students undergo hands-on laboratory training in C, C++, Core & Advanced Java, Python for Data Science, SQL, HTML5/CSS3, JavaScript, PHP, and modern cloud deployment environments.', 'academics', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('136', 'What is the total approved student intake across all SOET programs?', 'The total approved student intake capacity across all 8 B.Tech and M.Tech programs is 510 seats per academic year.', 'seats', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('137', 'What is the current seat availability and vacancy status?', 'Currently, 508 seats remain vacant out of 510 total intake capacity (2 seats confirmed filled in B.Tech CSE). Admissions are officially Open across all departments.', 'seats', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('138', 'How many seats are vacant specifically in B.Tech Computer Science & Engineering (CSE)?', 'In B.Tech CSE, 118 seats are vacant out of an approved intake capacity of 120 seats (2 seats confirmed filled).', 'seats', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('139', 'How many seats are available in AI/ML and Cyber Security specializations?', 'Both B.Tech CSE (AIML) and B.Tech CSE (Cyber Security) currently have 60 vacant seats each out of 60 approved seats (100% vacancy available).', 'seats', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('140', 'How many seats are vacant in core branches (Civil, Mechanical, ECE)?', 'Currently, 59 seats are vacant in ECE (out of 60), 60 seats are vacant in Mechanical (out of 60), and 60 seats are vacant in Civil Engineering (out of 60).', 'seats', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('141', 'How many total students are currently enrolled and registered?', 'Official admission database records confirm 2 enrolled students in B.Tech CSE, with overall enrollment actively progressing during the ongoing admission counseling rounds.', 'seats', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('142', 'What are the eligibility requirements for B.Tech engineering admissions?', 'Applicants must have passed 10+2 (HSC) with Physics and Mathematics as compulsory subjects, obtaining at least 45% aggregate marks (40% for reserved categories). Valid scores in MHT-CET or JEE Main are required.', 'admissions', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('143', 'Can non-CET candidates apply for direct institute-level quota admission?', 'Yes, candidates without MHT-CET or JEE Main scores can apply for Institute Level / Management Quota seats based on their 12th Standard PCM aggregate marks (minimum 45% for general, 40% for reserved category).', 'admissions', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('144', 'How can prospective students apply for admission?', 'Candidates can submit their application online through the official admissions portal at /admissions.php or visit the SOET Admission Counseling Cell at the university campus in person.', 'admissions', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('145', 'What documents are required during the admission process?', 'Required documents include 10th and 12th marksheets, MHT-CET/JEE score card, School Leaving Certificate (TC), Domicile/Nationality Certificate, and Caste/Validity certificates (if applying under reserved categories).', 'admissions', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('146', 'Are admissions currently open for the academic year?', 'Yes, admissions for the 2026 academic year are currently Open across all engineering branches, with 508 vacant seats available for counseling.', 'admissions', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('147', 'What is the annual tuition fee structure for B.Tech programs?', 'Annual tuition fees are: ₹150,000/year for B.Tech CSE, AIML, and Cyber Security; ₹140,000/year for ECE; and ₹130,000/year for Mechanical and Civil Engineering.', 'fees', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('148', 'What are the fees for the Integrated B.Tech and M.Tech programs?', 'The Integrated 6-Year B.Tech Program is priced at ₹110,000/year, and the M.Tech in CSE is priced at ₹100,000/year.', 'fees', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('149', 'What scholarships and financial assistance are available?', 'Government of Maharashtra scholarships (SC, ST, OBC, VJNT, EBC, SEBC) are supported via the MahaDBT portal. Additionally, MGM University awards institutional merit-based scholarships to high-performing students.', 'fees', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('150', 'How can tuition fees be paid?', 'Tuition fees can be paid online via Net Banking, Debit/Credit Card, or UPI on the student ERP portal, or offline via Demand Draft (DD) favoring \'MGM University SOET\' at the campus accounts counter.', 'fees', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('151', 'Who leads SOET MGM University?', 'SOET MGM University is led by Dr. Parminder Kaur Dhingra, Dean & Director. Under her leadership, the institution focuses on industry-aligned curricula, accredited research labs, and top-tier student placements.', 'faculty', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('152', 'Who are the Department Heads (HODs) at SOET?', 'The Computer Science & Engineering Department is headed by Dr. Sharad S. Gore, and the Mechanical Engineering Department is headed by Mr. Siddiqui Javed A.', 'faculty', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('153', 'What are the qualifications and experience of the teaching faculty?', 'Faculty members hold post-graduate (M.Tech/M.E.) and doctoral (Ph.D.) degrees with an average academic and research experience of 8 to 20+ years in emerging technological domains.', 'faculty', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('154', 'Which faculty members teach computer programming and AI?', 'Mrs. Deshmukh Rupali R. (M.Tech, specializing in Python & Image Processing) and Ms. Bhagat Chetana B. (M.Tech, specializing in Software Engineering & Java) guide computer programming and software development.', 'faculty', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('155', 'Where can students and parents view complete faculty profiles?', 'The comprehensive faculty directory—including contact emails, designations, and research publications—is published online on this website at /faculty.php.', 'faculty', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('156', 'What placement opportunities are available for engineering students?', 'The Training & Placement Cell facilitates campus recruitment with leading multinational IT and engineering corporations, achieving an average package of ₹4.8 LPA and top packages up to ₹14 LPA.', 'placements', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('157', 'Which major corporations recruit students from SOET?', 'Top recruiters include TCS, Infosys, Wipro, Capgemini, Tech Mahindra, Cognizant, L&T Infotech, and prominent core engineering firms in Maharashtra industrial hubs.', 'placements', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('158', 'What is the training and placement preparation process?', 'Students receive rigorous aptitude training, technical coding practice (Data Structures & Algorithms), soft skills enhancement, and mock technical/HR interview rounds starting from the pre-final year.', 'placements', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('159', 'Are industry internships mandatory and supported?', 'Yes, students complete mandatory industry internships during summer and winter vacations, organized in collaboration with university industry partners and MoU organizations.', 'placements', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('160', 'What campus facilities and infrastructure support technical education?', 'The campus features modern ICT-enabled smart classrooms, gigabit Wi-Fi connectivity, an Olympic-grade Sports Complex, boys and girls hostels, hygienic canteens, and an Innovation & Incubation Center.', 'facilities', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('161', 'What specialized laboratories are available on campus?', 'Laboratories include High-Performance Computing Labs, Artificial Intelligence & Machine Learning Lab, Cyber Forensics Sandbox, IoT & Robotics Lab, and Advanced CAD/CAM Simulation Centers.', 'facilities', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('162', 'Does the university campus have a central library?', 'Yes, the central library offers over 50,000 books, subscriptions to national/international research journals, digital access to IEEE/ScienceDirect databases, and spacious reading halls.', 'facilities', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('163', 'Where is SOET MGM University located and what is the address?', 'SOET is located at: MGM Campus, N-6, CIDCO, Chhatrapati Sambhajinagar (Aurangabad), Maharashtra - 431003, India.', 'facilities', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('164', 'What are the official contact numbers and email helplines?', 'Admission Helpline: +91-9371714253 / +91-240-2480570 | Official Email: admissionsoet@mgmu.ac.in / soet@mgmu.ac.in.', 'facilities', NULL, 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
