INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('1', 'SOET Overview & Campus Profile', 'general', 'School of Engineering & Technology (SOET) is a premier engineering constituent college of MGM University located in Chhatrapati Sambhajinagar (Aurangabad), Maharashtra, India. SOET offers cutting-edge B.Tech, M.Tech, and Ph.D. programs with state-of-the-art laboratories, industry tie-ups, and top-tier placement opportunities.', '/about.php', 'soet, mgm university, college, engineering, location, aurangabad, sambhajinagar, campus', 'active', '2026-08-11 15:22:44', '2026-08-11 15:22:44');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('2', 'B.Tech Admissions Process & Eligibility', 'admissions', 'Admissions to B.Tech programs at SOET are open for eligible candidates who have passed 10+2 (HSC) with Physics, Mathematics, and Chemistry/Biotechnology/Technical Vocational subjects securing at least 45% aggregate marks (40% for reserved categories). Valid scores in MHT-CET or JEE Main are preferred. Applications can be submitted online at http://localhost:8000/admissions.php.', '/admissions.php', 'admission, apply, eligibility, 12th percentage, cet, mht-cet, jee main, criteria, process, application', 'active', '2026-08-11 15:22:44', '2026-08-11 15:22:44');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('3', 'B.Tech Computer Science & Engineering (CSE)', 'programs', 'The CSE department at SOET offers a 4-year B.Tech in Computer Science & Engineering with an intake capacity of 120 seats. The curriculum covers Artificial Intelligence, Machine Learning, Cloud Computing, Cybersecurity, Full-Stack Web Development, and Data Structures. Total annual fee is RS 140000 per academic year.', '/courses.php', 'cse, computer science, btech cse, software, ai, ml, syllabus, duration, intake, fee', 'active', '2026-08-11 15:22:44', '2026-08-11 15:22:44');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('4', 'B.Tech Electronics & Telecommunication Engineering (ECE)', 'programs', 'The ECE department offers a 4-year B.Tech degree with 60 seats. Specializations include Internet of Things (IoT), VLSI Design, Embedded Systems, Signal Processing, and Wireless Communication. Annual fee is RS 130000.', '/courses.php', 'ece, electronics, telecommunication, iot, vlsi, embedded systems, robotics, fee', 'active', '2026-08-11 15:22:44', '2026-08-11 15:22:44');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('5', 'B.Tech Mechanical Engineering', 'programs', 'The Mechanical Engineering department offers a 4-year B.Tech with 60 seats, focusing on Robotics, CAD/CAM/CAE, Industry 4.0, Thermal Engineering, and EV (Electric Vehicles) technology. Annual fee is RS 125000.', '/courses.php', 'mechanical, mech, cad, cam, ev, robotics, manufacturing, fee, intake', 'active', '2026-08-11 15:22:44', '2026-08-11 15:22:44');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('6', 'B.Tech Civil Engineering', 'programs', 'The Civil Engineering department offers a 4-year B.Tech program with 60 seats specializing in Structural Engineering, Environmental Engineering, GIS & Remote Sensing, Smart City Construction Management. Annual fee is RS 120000.', '/courses.php', 'civil, construction, structural, gis, surveying, fee, intake', 'active', '2026-08-11 15:22:44', '2026-08-11 15:22:44');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('7', 'Leadership & Dean Profile', 'general', 'SOET MGM University is led by Dr. Parminder Kaur Dhingra, Dean & Director, SOET MGM University.\n\nLeadership Message:\n\"At SOET MGM University, we are committed to providing top-tier technological education with modern laboratories, expert faculty, and high-paying industry placements. Our mission is to produce innovative, ethically driven engineering professionals.\"', '/about.php', 'dean, director, rajesh kumar sen, leadership, principal, head, management', 'active', '2026-08-11 15:22:44', '2026-08-29 13:59:19');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('8', 'Training & Placements Overview', 'placements', 'The SOET Training & Placement Cell has achieved a 92% placement rate for recent batches. Top recruiting partners include TCS, Infosys, Wipro, Capgemini, Tech Mahindra, Cognizant, L&T Infotech, and Persistent Systems. Highest CTC offered: RS 18.5 LPA. Average CTC: RS 5.2 LPA.', '/placements.php', 'placement, salary, package, lpa, recruiter, tcs, infosys, wipro, jobs, hiring, companies', 'active', '2026-08-11 15:22:44', '2026-08-11 15:22:44');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('9', 'Infrastructure & Laboratories', 'departments', 'SOET boasts 35+ high-tech laboratories including NVIDIA AI & Deep Learning Lab, IoT & Robotics Innovation Lab, EV Testing Rig, High-Performance Computing Cluster, Smart Structural Lab, Central Digital Library with IEEE access, and 100 Mbps Wi-Fi enabled campus.', '/departments.php', 'lab, laboratory, infrastructure, nvidia, ai lab, wifi, library, computing, smart campus', 'active', '2026-08-11 15:22:44', '2026-08-11 15:22:44');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('10', 'Contact Information & Location', 'general', 'SOET, MGM University Campus, N-6, CIDCO, Chhatrapati Sambhajinagar (Aurangabad), Maharashtra 431003. Email: info@soet.edu | Phone: +91 98765 43210 | Official Website: http://localhost:8000', '/contact.php', 'contact, location, address, phone, email, map, reach, cidco, aurangabad, sambhajinagar', 'active', '2026-08-11 15:22:44', '2026-08-11 15:22:44');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('11', 'About SOET MGM University', 'general', 'The School of Engineering and Technology (SOET) is a premier constituent college of MGM University located in Chhatrapati Sambhajinagar (Aurangabad), Maharashtra. SOET is dedicated to providing high-quality, industry-aligned engineering education with modern infrastructure, state-of-the-art research laboratories, and experienced faculty.', '/about.php', 'soet, mgm university, mgmu, engineering college, about, overview, aurangabad, sambhajinagar', 'active', '2026-08-17 11:58:08', '2026-08-17 11:58:08');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('12', 'SOET Vision and Mission', 'general', 'Vision: To be a center of excellence in engineering education and research, fostering innovation, ethics, and leadership for global development. Mission: 1. To provide high-quality education in engineering and technology through modern pedagogical practices. 2. To promote interdisciplinary research and innovation addressing societal needs. 3. To build strong industry-academia partnerships for enhanced employability and entrepreneurial skills.', '/about.php', 'vision, mission, objectives, goals, soet vision, soet mission', 'active', '2026-08-17 11:58:08', '2026-08-17 11:58:08');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('13', 'Leadership - Dean & Director Details', 'general', 'Dr. Parminder Kaur Dhingra serves as the Dean & Director, SOET MGM University. She leads SOET towards continuous academic innovation, state-of-the-art laboratory infrastructure, research advancement, and high-paying industry placements.', '/about.php', 'director, dean, rajesh kumar sen, leadership, principal, administration', 'active', '2026-08-17 11:58:08', '2026-08-29 13:59:19');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('14', 'SOET B.Tech Programs Offered', 'general', 'SOET offers 4-Year B.Tech Degree Programs in: 1. Computer Science & Engineering (CSE) 2. CSE with specialization in Cyber Security 3. CSE with specialization in Data Science & Artificial Intelligence 4. Electronics & Telecommunication Engineering (ECE) 5. Mechanical Engineering 6. Civil Engineering 7. Robotics & Automation Engineering. Integrated 6-Year B.Tech programs after 10th (SSC) are also offered.', '/courses.php', 'btech, courses, programs, degrees, cse, ece, mechanical, civil, robotics, integrated btech', 'active', '2026-08-17 11:58:08', '2026-08-17 11:58:08');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('15', 'B.Tech Admission Eligibility Criteria', 'general', 'For 4-Year B.Tech: Candidates must have passed 10+2 (HSC) or equivalent examination with Physics and Mathematics as compulsory subjects along with Chemistry/Biotechnology/Biology/Technical Vocational subject, securing at least 45% aggregate marks (40% for reserved categories). Valid score in MHT-CET, JEE Main, or MGMU CET is required. For Integrated 6-Year B.Tech: Candidates must have passed 10th (SSC) with minimum 35% marks.', '/admissions.php', 'eligibility, criteria, percentage, 12th, 10th, hsc, ssc, mht-cet, jee main, mgmu cet, admission eligibility', 'active', '2026-08-17 11:58:08', '2026-08-17 11:58:08');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('16', 'SOET Admissions Procedure', 'general', 'Admission Procedure: 1. Online registration at MGM University portal (admissions.mgmu.ac.in). 2. Fill out application details and choose program preferences. 3. Appear for MGMU CET / submit valid MHT-CET or JEE Main scorecards. 4. Merit list generation and online counseling round. 5. Document verification and tuition fee payment at campus.', '/admissions.php', 'admission process, how to apply, registration, application form, counseling, merit list, document verification', 'active', '2026-08-17 11:58:08', '2026-08-17 11:58:08');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('17', 'SOET Fee Structure', 'general', 'The tuition fee for 4-Year B.Tech programs ranges approximately between INR 90,000 to INR 1,50,000 per academic year depending on the branch and category. Scholarship concessions are available for top CET scorers and deserving categories as per university guidelines.', '/courses.php', 'fees, fee structure, tuition fee, cost, per year fee, scholarship, concession', 'active', '2026-08-17 11:58:08', '2026-08-17 11:58:08');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('18', 'SOET Contact & Location Details', 'general', 'Address: School of Engineering and Technology (SOET), MGM University Campus, N-6, CIDCO, Chhatrapati Sambhajinagar (Aurangabad) - 431003, Maharashtra, India. Phone: 0240-6481000 / +91-9067612000. Email: contact@mgmu.ac.in / soet@mgmu.ac.in. Website: https://soet.mgmu.ac.in/', '/contact.php', 'contact, address, phone, email, location, map, cidco, aurangabad, sambhajinagar, reach us', 'active', '2026-08-17 11:58:08', '2026-08-17 11:58:08');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('19', 'SOET Facility: Central Library & Digital Resource Centre', 'facilities', 'Houses over 50,000+ technical volumes, IEEE e-journals, digital reading halls, e-learning stations, and 24/7 study areas for engineering students.', NULL, 'central library & digital resource centre, facility, campus, mgmu, soet, facilities', 'active', '2026-08-17 19:20:09', '2026-08-17 19:20:09');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('20', 'SOET Facility: Advanced Computing & AI Laboratories', 'facilities', 'State-of-the-art computer labs equipped with high-performance workstations, GPU acceleration, MATLAB, Python AI suites, and cloud computing infrastructure.', NULL, 'advanced computing & ai laboratories, facility, campus, mgmu, soet, facilities', 'active', '2026-08-17 19:20:10', '2026-08-17 19:20:10');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('21', 'SOET Facility: Robotics, IoT & Automation Lab', 'facilities', 'Hands-on robotics center featuring industrial robotic arms, microcontrollers, embedded IoT kits, drone development rigs, and 3D printing equipment.', NULL, 'robotics, iot & automation lab, facility, campus, mgmu, soet, facilities', 'active', '2026-08-17 19:20:10', '2026-08-17 19:20:10');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('22', 'SOET Facility: MGM Sports Complex & Olympic Swimming Pool', 'facilities', 'World-class sports infrastructure including an Olympic-sized swimming pool, indoor wooden badminton courts, gymnasium, cricket stadium, and shooting range.', NULL, 'mgm sports complex & olympic swimming pool, facility, campus, mgmu, soet, facilities', 'active', '2026-08-17 19:20:11', '2026-08-17 19:20:11');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('23', 'SOET Facility: 1500-Seater Grand University Auditorium', 'facilities', 'Acoustically designed, air-conditioned grand auditorium hosting national technical conferences, hackathons, convocation ceremonies, and cultural festivals.', NULL, '1500-seater grand university auditorium, facility, campus, mgmu, soet, facilities', 'active', '2026-08-17 19:20:11', '2026-08-17 19:20:11');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('24', 'SOET Facility: Campus Student Hostels (Boys & Girls)', 'facilities', 'Secure, modern residential hostels located within walking distance of academic blocks, offering AC and non-AC rooms, Wi-Fi, study lounges, and 24/7 security.', NULL, 'campus student hostels (boys & girls), facility, campus, mgmu, soet, facilities', 'active', '2026-08-17 19:20:12', '2026-08-17 19:20:12');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('25', 'SOET Facility: Innovation Incubation & Research Centre (IIRC)', 'facilities', 'Dedicated startup incubator supporting student entrepreneurs, patent filings, prototype fabrication, industry mentorship, and venture funding.', NULL, 'innovation incubation & research centre (iirc), facility, campus, mgmu, soet, facilities', 'active', '2026-08-17 19:20:12', '2026-08-17 19:20:12');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('26', 'SOET Facility: Modern Campus Cafeteria & Food Court', 'facilities', 'Hygienic multi-cuisine food court serving nutritious meals, fresh beverages, snacks, and outdoor seating spaces for relaxation.', NULL, 'modern campus cafeteria & food court, facility, campus, mgmu, soet, facilities', 'active', '2026-08-17 19:20:13', '2026-08-17 19:20:13');
