INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('106', 'Is hostellers laundry service free on campus?', 'general', 'SOET hostel residents have access to automated commercial laundry facilities and washing areas on campus. Basic laundry access is included in the hostel amenity fee, while specialized dry-cleaning services are available at nominal charges.', NULL, 'is hostellers laundry service free on campus? facilities', 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('107', 'Can non-CET candidates get direct management quota admission?', 'general', 'Yes, candidates who have not appeared for MHT-CET or JEE Main can apply for Institute Level / Management Quota seats based on their 12th Standard PCM aggregate marks (minimum 45% for general category, 40% for reserved categories). Direct counseling is conducted at the SOET Admission Office.', NULL, 'can non-cet candidates get direct management quota admission? admissions', 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('108', 'What is the schedule for inter-college sports tournaments?', 'general', 'The MGM University Annual Inter-College Sports Festival (including cricket, football, basketball, and athletics) is organized during the winter academic session (December–January). Exact fixture dates, venue schedules, and circulars are published under the Events and Notices section.', NULL, 'what is the schedule for inter-college sports tournaments? events', 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('109', 'check registration EVT-REG-2026-94628', 'general', 'Event registration pass EVT-REG-2026-94628 is valid for the scheduled university event. Attendees can present their digital event pass or confirmation SMS at the event check-in desk at the MGM University auditorium.', NULL, 'check registration evt-reg-2026-94628 events', 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('110', 'tell me about aerospace engineering syllabus at soet', 'general', 'This information is not currently available in our website database or official records, as SOET does not currently offer Aerospace Engineering. Available B.Tech degree branches include CSE, AI & ML, Cyber Security, ECE, Mechanical, and Civil Engineering.', NULL, 'tell me about aerospace engineering syllabus at soet academics', 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('111', 'coureses', 'general', 'SOET MGM University offers B.Tech programs in Civil, Computer Science, CSE (AI & ML), CSE (Cyber Security), ECE, Mechanical Engineering, Integrated 6-Year B.Tech (after 10th), and M.Tech in Computer Science & Engineering.', NULL, 'coureses academics', 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('112', 'live sae', 'general', 'Real-time engineering seat availability and vacancy metrics can be checked directly through CampusAI or on the Admissions portal, showing vacant versus filled seats across all B.Tech branches.', NULL, 'live sae admissions', 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
