INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('114', 'blogs', 'general', 'Explore student and faculty technical articles, campus stories, and innovation research on the official SOET Media Blog Portal at /blogs.php. Students can also submit new blog drafts via /submit-blog.php.', NULL, 'blogs general', 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('115', 'feedback', 'general', 'We welcome your suggestions and inquiries. You can share your feedback directly using the thumbs-up/down buttons in this chat, or submit an official contact message at /contact.php.', NULL, 'feedback general', 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('116', 'what is quantum computing', 'general', 'Quantum computing is a multidisciplinary field utilizing principles of quantum mechanics—such as superposition and entanglement—to perform complex computations exponentially faster than classical computers for specific problem classes.', NULL, 'what is quantum computing technical', 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('117', 'tell me about python', 'general', 'Python is a high-level, interpreted programming language renowned for its clean syntax and readability. It is widely used across web development, data science, automation, and artificial intelligence.', NULL, 'tell me about python technical', 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('118', 'what is date today', 'general', 'Today is Thursday, September 3, 2026.', NULL, 'what is date today general', 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('119', 'what is time now', 'general', 'The current time is tracked dynamically in Indian Standard Time (IST) via CampusAI.', NULL, 'what is time now general', 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('120', 'what is 25 * 4', 'general', '`25 * 4 = 100`', NULL, 'what is 25 * 4 general', 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('121', 'who are you', 'general', 'I am CampusAI, the official intelligent assistant for SOET MGM University, designed to answer college inquiries and general or technical questions directly.', NULL, 'who are you general', 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('122', 'who is prime minister of india', 'general', 'The Prime Minister of India is Narendra Modi, who has served as the head of government since May 2014.', NULL, 'who is prime minister of india general', 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('123', 'usa', 'general', 'The United States of America (USA) is a federal republic composed of 50 states, primarily located in North America, with its capital in Washington, D.C.', NULL, 'usa general', 'active', '2026-09-03 00:28:47', '2026-09-03 00:28:47');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('124', 'What is artificial intelligence (AI)?', 'ai_tech', 'Artificial Intelligence (AI) is the branch of computer science dedicated to developing software systems capable of performing tasks that typically require human cognition, such as reasoning, problem-solving, visual perception, and decision-making.', NULL, 'what is artificial intelligence (ai)? ai_tech', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:41');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('125', 'What is machine learning (ML)?', 'ai_tech', 'Machine learning is a subset of AI where mathematical algorithms learn statistical patterns from historical data to make predictions or automated decisions without being explicitly programmed.', NULL, 'what is machine learning (ml)? ai_tech', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:41');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('126', 'What is ChatGPT?', 'ai_tech', 'ChatGPT is an artificial intelligence conversational model developed by OpenAI. Built on Large Language Models (LLMs), it engages in natural dialogue, writes and debugs code, and synthesizes complex information.', NULL, 'what is chatgpt? ai_tech', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:41');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('127', 'What is cybersecurity?', 'ai_tech', 'Cybersecurity is the practice of protecting computer systems, cloud networks, digital devices, and sensitive organizational data from unauthorized access, cyberattacks, theft, and damage.', NULL, 'what is cybersecurity? ai_tech', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:41');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('128', 'What is the Internet of Things (IoT)?', 'ai_tech', 'The Internet of Things (IoT) refers to an interconnected network of physical devices embedded with sensors, microcontrollers, and wireless connectivity that autonomously collect and exchange operational data in real time.', NULL, 'what is the internet of things (iot)? ai_tech', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:41');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('129', 'What is blockchain technology?', 'ai_tech', 'Blockchain is a decentralized, cryptographically secured distributed digital ledger that chronologically records transactions across a peer-to-peer network, ensuring tamper-proof immutability without requiring a central intermediary.', NULL, 'what is blockchain technology? ai_tech', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:41');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('130', 'What is data science?', 'ai_tech', 'Data science is an interdisciplinary field combining statistics, advanced mathematics, domain expertise, and machine learning programming to discover actionable patterns and predictive insights from structured and unstructured data.', NULL, 'what is data science? ai_tech', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:41');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('131', 'What is quantum computing?', 'ai_tech', 'Quantum computing harnesses fundamental principles of quantum mechanics—such as superposition and quantum entanglement—to solve specialized mathematical and optimization problems exponentially faster than classical supercomputers.', NULL, 'what is quantum computing? ai_tech', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:41');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('132', 'What is digital transformation?', 'ai_tech', 'Digital transformation is the strategic integration of modern digital technology across all operational areas of an organization, fundamentally modernizing operational efficiency and customer value delivery.', NULL, 'what is digital transformation? ai_tech', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:41');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('133', 'What is Python?', 'programming', 'Python is a high-level, interpreted programming language known for its concise syntax and dynamic typing. It is widely used across backend web development, data science, scientific computing, automation, and artificial intelligence.', NULL, 'what is python? programming', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:41');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('134', 'What is Java and how does it achieve portability?', 'programming', 'Java is an object-oriented, class-based language built on the \'Write Once, Run Anywhere\' (WORA) philosophy. Compiled Java bytecode executes within a Java Virtual Machine (JVM), ensuring seamless cross-platform execution.', NULL, 'what is java and how does it achieve portability? programming', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:41');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('135', 'What is C++ and where is it primarily used?', 'programming', 'C++ is a high-performance compiled language that combines low-level memory control with object-oriented abstractions. It is the industry standard for game engines, operating system components, embedded firmware, and low-latency financial systems.', NULL, 'what is c++ and where is it primarily used? programming', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('136', 'What is the difference between HTML and CSS?', 'programming', 'HTML (HyperText Markup Language) constructs the structural content and semantic hierarchy of a webpage, whereas CSS (Cascading Style Sheets) specifies visual presentation, layout styling, typography, colors, and responsive animations.', NULL, 'what is the difference between html and css? programming', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('137', 'What is JavaScript and Node.js?', 'programming', 'JavaScript is a dynamic, lightweight scripting language that powers interactive frontend user experiences. With Node.js, JavaScript executes server-side, enabling unified full-stack web application development.', NULL, 'what is javascript and node.js? programming', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('138', 'What is Object-Oriented Programming (OOP) and its core pillars?', 'programming', 'Object-Oriented Programming (OOP) is a software design paradigm structured around reusable classes and stateful objects, governed by four core pillars: Encapsulation, Abstraction, Inheritance, and Polymorphism.', NULL, 'what is object-oriented programming (oop) and its core pillars? programming', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('139', 'What is the difference between a class and an object?', 'programming', 'A class is an abstract architectural blueprint defining member properties and methods, while an object is a concrete, self-contained instance instantiated in memory holding actual state data.', NULL, 'what is the difference between a class and an object? programming', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('140', 'What is an Application Programming Interface (API) and REST?', 'programming', 'An API is a defined set of communication protocols enabling independent software applications to interact. A REST API leverages standard HTTP methods (GET, POST, PUT, DELETE) and stateless JSON data exchange.', NULL, 'what is an application programming interface (api) and rest? programming', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('141', 'What is Git and how does GitHub complement it?', 'programming', 'Git is a distributed command-line version control system that tracks source code revisions locally, while GitHub is a cloud platform that hosts remote Git repositories, facilitating pull requests, code reviews, and team collaboration.', NULL, 'what is git and how does github complement it? programming', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('142', 'What is Docker and containerization?', 'programming', 'Docker packages applications and their exact runtime dependencies into lightweight, isolated containers, guaranteeing consistent execution across local development, staging servers, and cloud production environments.', NULL, 'what is docker and containerization? programming', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('143', 'What is a Database Management System (DBMS)?', 'databases', 'A DBMS is system software that manages structured data storage, retrieval, and concurrency while enforcing ACID transaction properties (Atomicity, Consistency, Isolation, Durability).', NULL, 'what is a database management system (dbms)? databases', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('144', 'What is the difference between a primary key and a foreign key?', 'databases', 'A primary key uniquely identifies each individual row within its own table (strictly non-null and unique), whereas a foreign key references a primary key in another table to establish referential relationships.', NULL, 'what is the difference between a primary key and a foreign key? databases', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('145', 'What is database normalization and why is it important?', 'databases', 'Normalization is the systematic design process of structuring database tables (from 1NF to BCNF) to eliminate redundant data duplication and prevent insertion, update, and deletion anomalies.', NULL, 'what is database normalization and why is it important? databases', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('146', 'What is CRUD in database applications?', 'databases', 'CRUD is an industry acronym for Create, Read, Update, and Delete—the four foundational operations implemented across persistent database storage and RESTful software APIs.', NULL, 'what is crud in database applications? databases', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('147', 'What is an Operating System (OS)?', 'databases', 'An operating system is fundamental system software that coordinates computer hardware, allocates CPU processing time, manages RAM memory and storage I/O, and provides an execution platform for user applications.', NULL, 'what is an operating system (os)? databases', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('148', 'What is binary search algorithm?', 'databases', 'Binary search is an efficient O(log n) divide-and-conquer algorithm that locates a target value in a sorted collection by repeatedly halving the search interval.', NULL, 'what is binary search algorithm? databases', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('149', 'What is an IP address?', 'databases', 'An IP address (IPv4/IPv6) is a unique numerical network identifier assigned to every hardware device connected to an IP-based computer network for routing packets.', NULL, 'what is an ip address? databases', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('150', 'What degree programs and engineering branches are offered at SOET?', 'academics', 'SOET offers 8 approved programs: B.Tech in Civil, Computer Science & Engineering (CSE), CSE (AI & ML), CSE (Cyber Security), ECE, Mechanical Engineering, an Integrated 6-Year B.Tech (after 10th), and M.Tech in CSE.', NULL, 'what degree programs and engineering branches are offered at soet? academics', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('151', 'What are the details of the B.Tech Computer Science & Engineering (CSE) program?', 'academics', 'B.Tech CSE is a 4-year (8 semesters) program with an approved intake of 120 seats. The curriculum covers Data Structures, Algorithms, Operating Systems, Database Management, Cloud Computing, and Full-Stack Development.', NULL, 'what are the details of the b.tech computer science & engineering (cse) program? academics', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('152', 'Does SOET offer specialized programs in Artificial Intelligence and Machine Learning?', 'academics', 'Yes, SOET offers B.Tech in CSE (Artificial Intelligence & Machine Learning) with an approved intake of 60 seats. Coursework includes Neural Networks, Deep Learning, Computer Vision, and Natural Language Processing.', NULL, 'does soet offer specialized programs in artificial intelligence and machine learning? academics', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('153', 'What program is available for students interested in Cyber Security?', 'academics', 'SOET offers B.Tech in CSE (Cyber Security & Digital Forensics) (60 seats intake), emphasizing Network Security, Ethical Hacking, Cryptographic Protocols, Digital Forensics, and Threat Intelligence.', NULL, 'what program is available for students interested in cyber security? academics', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('154', 'What programs are available after 10th Class?', 'academics', 'SOET offers an Integrated 6-Year B.Tech Program (INT-BTECH) with an intake of 60 seats, allowing SSC (10th) passed students to complete both diploma-level foundations and a full engineering degree.', NULL, 'what programs are available after 10th class? academics', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('155', 'What post-graduate (M.Tech) engineering programs are available?', 'academics', 'The college offers M.Tech in Computer Science & Engineering (MTECH-CSE), a 2-year (4 semesters) advanced research degree with an annual intake capacity of 30 seats.', NULL, 'what post-graduate (m.tech) engineering programs are available? academics', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('156', 'What programming languages are taught in the engineering curricula?', 'academics', 'Students undergo hands-on laboratory training in C, C++, Core & Advanced Java, Python for Data Science, SQL, HTML5/CSS3, JavaScript, PHP, and modern cloud deployment environments.', NULL, 'what programming languages are taught in the engineering curricula? academics', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('157', 'What is the total approved student intake across all SOET programs?', 'seats', 'The total approved student intake capacity across all 8 B.Tech and M.Tech programs is 510 seats per academic year.', NULL, 'what is the total approved student intake across all soet programs? seats', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('158', 'What is the current seat availability and vacancy status?', 'seats', 'Currently, 508 seats remain vacant out of 510 total intake capacity (2 seats confirmed filled in B.Tech CSE). Admissions are officially Open across all departments.', NULL, 'what is the current seat availability and vacancy status? seats', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('159', 'How many seats are vacant specifically in B.Tech Computer Science & Engineering (CSE)?', 'seats', 'In B.Tech CSE, 118 seats are vacant out of an approved intake capacity of 120 seats (2 seats confirmed filled).', NULL, 'how many seats are vacant specifically in b.tech computer science & engineering (cse)? seats', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('160', 'How many seats are available in AI/ML and Cyber Security specializations?', 'seats', 'Both B.Tech CSE (AIML) and B.Tech CSE (Cyber Security) currently have 60 vacant seats each out of 60 approved seats (100% vacancy available).', NULL, 'how many seats are available in ai/ml and cyber security specializations? seats', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('161', 'How many seats are vacant in core branches (Civil, Mechanical, ECE)?', 'seats', 'Currently, 59 seats are vacant in ECE (out of 60), 60 seats are vacant in Mechanical (out of 60), and 60 seats are vacant in Civil Engineering (out of 60).', NULL, 'how many seats are vacant in core branches (civil, mechanical, ece)? seats', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('162', 'How many total students are currently enrolled and registered?', 'seats', 'Official admission database records confirm 2 enrolled students in B.Tech CSE, with overall enrollment actively progressing during the ongoing admission counseling rounds.', NULL, 'how many total students are currently enrolled and registered? seats', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('163', 'What are the eligibility requirements for B.Tech engineering admissions?', 'admissions', 'Applicants must have passed 10+2 (HSC) with Physics and Mathematics as compulsory subjects, obtaining at least 45% aggregate marks (40% for reserved categories). Valid scores in MHT-CET or JEE Main are required.', NULL, 'what are the eligibility requirements for b.tech engineering admissions? admissions', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('164', 'Can non-CET candidates apply for direct institute-level quota admission?', 'admissions', 'Yes, candidates without MHT-CET or JEE Main scores can apply for Institute Level / Management Quota seats based on their 12th Standard PCM aggregate marks (minimum 45% for general, 40% for reserved category).', NULL, 'can non-cet candidates apply for direct institute-level quota admission? admissions', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('165', 'How can prospective students apply for admission?', 'admissions', 'Candidates can submit their application online through the official admissions portal at /admissions.php or visit the SOET Admission Counseling Cell at the university campus in person.', NULL, 'how can prospective students apply for admission? admissions', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('166', 'What documents are required during the admission process?', 'admissions', 'Required documents include 10th and 12th marksheets, MHT-CET/JEE score card, School Leaving Certificate (TC), Domicile/Nationality Certificate, and Caste/Validity certificates (if applying under reserved categories).', NULL, 'what documents are required during the admission process? admissions', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('167', 'Are admissions currently open for the academic year?', 'admissions', 'Yes, admissions for the 2026 academic year are currently Open across all engineering branches, with 508 vacant seats available for counseling.', NULL, 'are admissions currently open for the academic year? admissions', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('168', 'What is the annual tuition fee structure for B.Tech programs?', 'fees', 'Annual tuition fees are: ₹150,000/year for B.Tech CSE, AIML, and Cyber Security; ₹140,000/year for ECE; and ₹130,000/year for Mechanical and Civil Engineering.', NULL, 'what is the annual tuition fee structure for b.tech programs? fees', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('169', 'What are the fees for the Integrated B.Tech and M.Tech programs?', 'fees', 'The Integrated 6-Year B.Tech Program is priced at ₹110,000/year, and the M.Tech in CSE is priced at ₹100,000/year.', NULL, 'what are the fees for the integrated b.tech and m.tech programs? fees', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('170', 'What scholarships and financial assistance are available?', 'fees', 'Government of Maharashtra scholarships (SC, ST, OBC, VJNT, EBC, SEBC) are supported via the MahaDBT portal. Additionally, MGM University awards institutional merit-based scholarships to high-performing students.', NULL, 'what scholarships and financial assistance are available? fees', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('171', 'How can tuition fees be paid?', 'fees', 'Tuition fees can be paid online via Net Banking, Debit/Credit Card, or UPI on the student ERP portal, or offline via Demand Draft (DD) favoring \'MGM University SOET\' at the campus accounts counter.', NULL, 'how can tuition fees be paid? fees', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('172', 'Who leads SOET MGM University?', 'faculty', 'SOET MGM University is led by Dr. Parminder Kaur Dhingra, Dean & Director. Under her leadership, the institution focuses on industry-aligned curricula, accredited research labs, and top-tier student placements.', NULL, 'who leads soet mgm university? faculty', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('173', 'Who are the Department Heads (HODs) at SOET?', 'faculty', 'The Computer Science & Engineering Department is headed by Dr. Sharad S. Gore, and the Mechanical Engineering Department is headed by Mr. Siddiqui Javed A.', NULL, 'who are the department heads (hods) at soet? faculty', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('174', 'What are the qualifications and experience of the teaching faculty?', 'faculty', 'Faculty members hold post-graduate (M.Tech/M.E.) and doctoral (Ph.D.) degrees with an average academic and research experience of 8 to 20+ years in emerging technological domains.', NULL, 'what are the qualifications and experience of the teaching faculty? faculty', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('175', 'Which faculty members teach computer programming and AI?', 'faculty', 'Mrs. Deshmukh Rupali R. (M.Tech, specializing in Python & Image Processing) and Ms. Bhagat Chetana B. (M.Tech, specializing in Software Engineering & Java) guide computer programming and software development.', NULL, 'which faculty members teach computer programming and ai? faculty', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('176', 'Where can students and parents view complete faculty profiles?', 'faculty', 'The comprehensive faculty directory—including contact emails, designations, and research publications—is published online on this website at /faculty.php.', NULL, 'where can students and parents view complete faculty profiles? faculty', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('177', 'What placement opportunities are available for engineering students?', 'placements', 'The Training & Placement Cell facilitates campus recruitment with leading multinational IT and engineering corporations, achieving an average package of ₹4.8 LPA and top packages up to ₹14 LPA.', NULL, 'what placement opportunities are available for engineering students? placements', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('178', 'Which major corporations recruit students from SOET?', 'placements', 'Top recruiters include TCS, Infosys, Wipro, Capgemini, Tech Mahindra, Cognizant, L&T Infotech, and prominent core engineering firms in Maharashtra industrial hubs.', NULL, 'which major corporations recruit students from soet? placements', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('179', 'What is the training and placement preparation process?', 'placements', 'Students receive rigorous aptitude training, technical coding practice (Data Structures & Algorithms), soft skills enhancement, and mock technical/HR interview rounds starting from the pre-final year.', NULL, 'what is the training and placement preparation process? placements', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('180', 'Are industry internships mandatory and supported?', 'placements', 'Yes, students complete mandatory industry internships during summer and winter vacations, organized in collaboration with university industry partners and MoU organizations.', NULL, 'are industry internships mandatory and supported? placements', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('181', 'What campus facilities and infrastructure support technical education?', 'facilities', 'The campus features modern ICT-enabled smart classrooms, gigabit Wi-Fi connectivity, an Olympic-grade Sports Complex, boys and girls hostels, hygienic canteens, and an Innovation & Incubation Center.', NULL, 'what campus facilities and infrastructure support technical education? facilities', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('182', 'What specialized laboratories are available on campus?', 'facilities', 'Laboratories include High-Performance Computing Labs, Artificial Intelligence & Machine Learning Lab, Cyber Forensics Sandbox, IoT & Robotics Lab, and Advanced CAD/CAM Simulation Centers.', NULL, 'what specialized laboratories are available on campus? facilities', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('183', 'Does the university campus have a central library?', 'facilities', 'Yes, the central library offers over 50,000 books, subscriptions to national/international research journals, digital access to IEEE/ScienceDirect databases, and spacious reading halls.', NULL, 'does the university campus have a central library? facilities', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('184', 'Where is SOET MGM University located and what is the address?', 'facilities', 'SOET is located at: MGM Campus, N-6, CIDCO, Chhatrapati Sambhajinagar (Aurangabad), Maharashtra - 431003, India.', NULL, 'where is soet mgm university located and what is the address? facilities', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
INSERT INTO `knowledge_base` (`id`, `title`, `category`, `content`, `source_url`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('185', 'What are the official contact numbers and email helplines?', 'facilities', 'Admission Helpline: +91-9371714253 / +91-240-2480570 | Official Email: admissionsoet@mgmu.ac.in / soet@mgmu.ac.in.', NULL, 'what are the official contact numbers and email helplines? facilities', 'active', '2026-09-03 00:49:41', '2026-09-03 00:49:42');
