INSERT INTO `sub_events` (`id`, `event_id`, `title`, `sub_event_date`, `sub_event_time`, `venue`, `coordinator`, `max_participants`, `description`, `rules`, `is_active`, `created_at`) VALUES ('1', '2', 'Code-A-Thon (36-Hour Hackathon)', '2026-08-27', '10:00:00', 'Central Computer Lab 3', 'Prof. Anujkumar Domale', '100', 'Inter-college 36-hour continuous software development and problem solving competition.', 'Teams of 2-4 members. Bring your own laptops. Internet provided.', '1', '2026-08-26 14:37:44');
INSERT INTO `sub_events` (`id`, `event_id`, `title`, `sub_event_date`, `sub_event_time`, `venue`, `coordinator`, `max_participants`, `description`, `rules`, `is_active`, `created_at`) VALUES ('2', '2', 'Robo Wars & Obstacle Race', '2026-08-27', '14:00:00', 'SOET Open Courtyard Arena', 'Dr. Eknath Pawar', '50', 'Wired and wireless bot combat and obstacle course navigation challenge.', 'Bot weight limit 15kg. Battery voltage max 24V.', '1', '2026-08-26 14:37:44');
