INSERT INTO `unanswered_questions` (`id`, `session_id`, `question`, `category`, `confidence`, `status`, `admin_response`, `created_at`) VALUES ('6', NULL, 'Is hostellers laundry service free on campus?', 'facilities', '0.45', 'answered', 'SOET hostel residents have access to automated commercial laundry facilities and washing areas on campus. Basic laundry access is included in the hostel amenity fee, while specialized dry-cleaning services are available at nominal charges.', '2026-08-26 14:15:30');
INSERT INTO `unanswered_questions` (`id`, `session_id`, `question`, `category`, `confidence`, `status`, `admin_response`, `created_at`) VALUES ('7', NULL, 'Can non-CET candidates get direct management quota admission?', 'admissions', '0.45', 'answered', 'Yes, candidates who have not appeared for MHT-CET or JEE Main can apply for Institute Level / Management Quota seats based on their 12th Standard PCM aggregate marks (minimum 45% for general category, 40% for reserved categories). Direct counseling is conducted at the SOET Admission Office.', '2026-08-26 14:15:30');
INSERT INTO `unanswered_questions` (`id`, `session_id`, `question`, `category`, `confidence`, `status`, `admin_response`, `created_at`) VALUES ('8', NULL, 'What is the schedule for inter-college sports tournaments?', 'events', '0.45', 'answered', 'The MGM University Annual Inter-College Sports Festival (including cricket, football, basketball, and athletics) is organized during the winter academic session (December–January). Exact fixture dates, venue schedules, and circulars are published under the Events and Notices section.', '2026-08-26 14:15:30');
