-- ========================================================
-- Table: courses
-- Purpose: Academic degree programs, specializations, and seat allocation master table.
-- Details:
--   - Stores program name, course code (e.g., 'BTECH-CSE'), duration in years, and semester count.
--   - Manages live seat capacity (intake_capacity vs filled_seats) and admission status ('OPEN', 'CLOSED', 'PAUSED').
--   - Contains annual fee breakdowns (fee_year_1 through fee_year_4) and syllabus PDF paths.
--   - Real-time seat inventory is queried directly by CampusAI and admission forms.
-- Relationships:
--   - department_id -> departments(id) ON DELETE CASCADE
-- Indexes:
--   - code (UNIQUE): Academic course identifier code.
--   - idx_active_status: Fast filtering for active programs accepting admissions.
-- ========================================================
DROP TABLE IF EXISTS `courses`;
CREATE TABLE `courses` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `department_id` int(11) NOT NULL,
  `name` varchar(100) NOT NULL,
  `code` varchar(20) NOT NULL,
  `description` text DEFAULT NULL,
  `image_path` varchar(255) DEFAULT NULL,
  `duration_years` int(11) DEFAULT 4,
  `semester_count` int(11) DEFAULT 8,
  `intake_capacity` int(11) DEFAULT 60,
  `filled_seats` int(11) NOT NULL DEFAULT 0,
  `admission_status` enum('OPEN','CLOSED','PAUSED') NOT NULL DEFAULT 'OPEN',
  `fee_year_1` decimal(10,2) DEFAULT 150000.00,
  `fee_year_2` decimal(10,2) DEFAULT 150000.00,
  `fee_year_3` decimal(10,2) DEFAULT 150000.00,
  `fee_year_4` decimal(10,2) DEFAULT 150000.00,
  `syllabus_pdf_year_1` varchar(255) DEFAULT NULL,
  `syllabus_pdf_year_2` varchar(255) DEFAULT NULL,
  `syllabus_pdf_year_3` varchar(255) DEFAULT NULL,
  `syllabus_pdf_year_4` varchar(255) DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`),
  KEY `department_id` (`department_id`),
  KEY `idx_active_status` (`is_active`,`admission_status`),
  CONSTRAINT `courses_ibfk_1` FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ========================================================
-- Table: departments
-- Purpose: Engineering and academic departments organizational hierarchy.
